 439|static __attribute__((always_inline)) inline jx_glut4 jx_glut4_load(void)
 440|{
 441|  jx_glut4 k;
 442|  k.off = jx_kt[48]; k.scale = jx_kt[49];
 443|  k.hi  = jx_kt[50]; k.lo    = jx_kt[51];
