 493|{
 494|  (void)E;
 495|  const float hi = jx_kt[50];
 496|  {
 497|    float t = x * jx_kt[49] + jx_kt[48];
 498|    int   i = (int)t;
 499|    i = (i < 0) ? 0 : i;
 500|    i = (i > (JX_GLUT_N - 2)) ? (JX_GLUT_N - 2) : i;
 501|    float f = t - (float)i;
 502|    float a = jx_glut[i], b = jx_glut[i + 1];
 503|    float y = a + f * (b - a);
 504|    JX_FSELHI_ASM(y, x, hi);
 505|    return y;
 506|  }
 507|}
