 509|/* r119：把 jx_kt[48..51] 与 LUT 基址**提到循环外**的版本。
 510| * 动机（r118 固件反汇编，jx_conv1d_k1_cf_tb 的 post==1 epilogue）：
 511| * 每个元素里都有 3 条 `l32r`（从 flash 字面池重取 jx_kt/jx_glut 地址）
 512| * 与 3 条 `lsi`（重读 jx_kt[48..51]）—— 因为 dst 是 float*、jx_kt 也是
 513| * float[]，严格别名规则下 GCC 必须假设每次 `dst[j]=` 都可能改到它们。
 514| * 结果 26 条指令/元素全部串行，4 路展开被排成 4 段独立代码，延迟完全暴露
 515| * （实测 48.9 周期/元素）。
 516| * 把 off/scale/hi 与表基址作为参数传进来、并在调用点配 __restrict 输出后，
 517| * 这些加载可以彻底提到循环外，4 条 lane 也能被交错。
 518| * 算式与 jx_gelu_fast 逐项相同 -> 逐位一致。 */
 519|static __attribute__((always_inline)) inline float jx_gelu_kt(float x, jx_glut4 K,
 520|                                                              const float *lut)
 521|{
 522|  float t = x * K.scale + K.off;
 523|  int   i = (int)t;
 524|  i = (i < 0) ? 0 : i;
 525|  i = (i > (JX_GLUT_N - 2)) ? (JX_GLUT_N - 2) : i;
 526|  float f = t - (float)i;
 527|  float a = lut[i], b = lut[i + 1];
 528|  float y = a + f * (b - a);
 529|  JX_FSELHI_ASM(y, x, K.hi);
 530|  return y;
