 540| * 的 4 条指令互不依赖，正好盖住 FPU 延迟；段与段之间不要求同时保活 4 份
 541| * 中间量，峰值活跃寄存器降到 ~12。
 542| * 每个元素自己的下标钳位、算式与 jx_gelu_fast 完全相同（交错只发生在不同
 543| * 元素之间），结果逐位一致。 */
 544|static __attribute__((always_inline)) inline void jx_gelu4_fast(
 545|    float x0, float x1, float x2, float x3, jx_erf9 E,
 546|    float *r0, float *r1, float *r2, float *r3)
 547|{
 548|  (void)E;
 549|  const float hi   = jx_kt[50];
 550|  const float sc   = jx_kt[49], of = jx_kt[48];
 551|  const int   imax = JX_GLUT_N - 2;
 552|  float t0 = x0 * sc + of, t1 = x1 * sc + of;
 553|  float t2 = x2 * sc + of, t3 = x3 * sc + of;
 554|  int i0 = (int)t0, i1 = (int)t1, i2 = (int)t2, i3 = (int)t3;
 555|  i0 = (i0 < 0) ? 0 : i0; i0 = (i0 > imax) ? imax : i0;
 556|  i1 = (i1 < 0) ? 0 : i1; i1 = (i1 > imax) ? imax : i1;
