void encoder_forward(const T *x, T *out) {
    JXP_BEG(JP_ENCODER);
    int B = x->shape[0], T0 = x->shape[2];
    T cur = t_alloc(3, (int[]){B, 1, T0}); t_copy(&cur, x);
    T b = t_alloc(3, (int[]){B, ENC_DIMS[0], T0}); first_block(&cur, &b); t_free(&cur); cur = b;
    int Tprev = T0;
