  29:         char wn[64], bn[64], cn[64], cbn[64];
  30:         snprintf(wn, sizeof(wn), "encoder.blocks.%d.0.weight", 2*i + 2);
  31:         snprintf(bn, sizeof(bn), "encoder.blocks.%d.0.bias", 2*i + 2);
  32:         snprintf(cn, sizeof(cn), "encoder.blocks.%d.1.weight", 2*i + 2);
  33:         snprintf(cbn, sizeof(cbn), "encoder.blocks.%d.1.bias", 2*i + 2);
  34:         printf("  [CU2] i=%d cur.d=%p len=%d\n", i, (void *)cur.d, (int)cur.len);
  35:         { char nm[32]; snprintf(nm, sizeof(nm), "enc.s%d.cu2", i); jx_stage_h(nm, cur.d, (size_t)cur.len * sizeof(float)); }
  36:         conv1d(W_(wn), W_(bn), &cur, &dn, Ci, Co, st, st, 0, 1, Tprev);
