  57: /* ============================ LocalEncoder.forward ============================ */
  58: void en_encoder_forward(const T *x, T *out) {
  59:     JXP_BEG(JP_ENENCODER);
  60:     /* x[B,C,T'] -> permute [B,T',C] -> LocalTrans stack -> out[B,T',C] */
  61:     int B = x->shape[0], C = x->shape[1], Tt = x->shape[2];
  62:     T pl = t_alloc(3, (int[]){B, Tt, C});
  63:     JXP_BEG(JP_PERMUTE);
  64:     for (int bi = 0; bi < B; bi++) for (int t = 0; t < Tt; t++) for (int c = 0; c < C; c++)
  65:         pl.d[(bi*Tt+t)*C+c] = x->d[(bi*C+c)*Tt+t];
  66:     JXP_END(JP_PERMUTE);
  67: 
  68:     if (EN_USE_COMPRESSED) {
  69:         /* CompressedLocalEncoderWithCache:
  70:          *   down_trans.trans = LocalTrans(depth=EN_ENC_DOWN_DEPTH, win=EN_ENC_DOWN_WIN)
  71:          *   down_trans.down_layer = Conv1d(k=rate, s=rate)  -> T' -> T'/rate
  72:          *   local_trans = LocalTrans(depth=EN_ENC_LOCAL_DEPTH, win=EN_ENC_LOCAL_WIN) */
  73:         T dt;                       /* local_transformer 自己分配并交接出来 */
  74:         local_transformer(&pl, &dt, "en_encoder.down_trans.trans", EN_ENC_DOWN_DEPTH, EN_ENC_DOWN_WIN);
  75:         t_free(&pl);
  76:         /* down_layer: permute (B,T,C)->(B,C,T), conv1d k=s=rate, permute back */
  77:         int Td = Tt / EN_ENC_COMPRESS_RATE;   /* Tt is divisible by rate */
  78:         T dtc = t_alloc(3, (int[]){B, C, Tt});
  79:         for (int bi = 0; bi < B; bi++) for (int t = 0; t < Tt; t++) for (int c = 0; c < C; c++)
  80:             dtc.d[(bi*C+c)*Tt+t] = dt.d[(bi*Tt+t)*C+c];
  81:         t_free(&dt);
  82:         T dconv = t_alloc(3, (int[]){B, C, Td});
  83:         conv1d(W_("en_encoder.down_trans.down_layer.weight"), W_("en_encoder.down_trans.down_layer.bias"),
  84:                &dtc, &dconv, C, C, EN_ENC_COMPRESS_RATE, EN_ENC_COMPRESS_RATE, 0, 1, Tt);
  85:         t_free(&dtc);
  86:         T dconvp = t_alloc(3, (int[]){B, Td, C});
  87:         for (int bi = 0; bi < B; bi++) for (int t = 0; t < Td; t++) for (int c = 0; c < C; c++)
  88:             dconvp.d[(bi*Td+t)*C+c] = dconv.d[(bi*C+c)*Td+t];
  89:         t_free(&dconv);
  90:         T lt;                       /* 同上，避免再把一份全尺寸占位块丢掉 */
  91:         local_transformer(&dconvp, &lt, "en_encoder.local_trans", EN_ENC_LOCAL_DEPTH, EN_ENC_LOCAL_WIN);
  92:         t_free(&dconvp);
  93:         *out = lt;
  94:     } else {
  95:         T tr;                       /* 同上 */
  96:         local_transformer(&pl, &tr, "en_encoder.local_trans", EN_ENC_DEPTH, EN_WINDOW);
  97:         t_free(&pl);
  98:         *out = tr;
  99:     }
 100:     JXP_END(JP_ENENCODER);
 101: }

