#define JX_AMAGIC 0x4a58a11cu
static jx_ahdr_t *jx_ahdr_of(void *p)
{ return (jx_ahdr_t *)(void *)((unsigned char *)p - sizeof(jx_ahdr_t)); }
void *jx_amalloc(size_t bytes)
{
