  cp = ((size_t)h->bytes < newbytes) ? (size_t)h->bytes : newbytes;
  memcpy(n, p, cp);
  free(h->raw);
  return n;
}
void jx_afree(void *p)
{
  jx_ahdr_t *h;
  if (p == NULL) { return; }
  h = jx_ahdr_of(p);
  if (h->magic == JX_AMAGIC) { free(h->raw); } else { free(p); }
}

