+      *cp = ((uint32_t)(c & 0x07u) << 18) |
+            ((uint32_t)((unsigned char)s[0] & 0x3fu) << 12) |
+            ((uint32_t)((unsigned char)s[1] & 0x3fu) << 6) |
+            ((uint32_t)((unsigned char)s[2] & 0x3fu));
+      return s + 3;
+    }
+
+  *cp = '?';
+  return s;
+}
+
+static int str_chars(const char *s)
+{
+  int n = 0;
+  uint32_t cp;
+
+  while (*s != '\0') { s = u8next(s, &cp); n++; }
+  return n;
+}
+
+/****************************************************************************
+ * 字库
+ ****************************************************************************/
+
+/* 文件格式（小端）：
+ *   0  : "JXFN"
+ *   4  : u16 字宽   6: u16 字高
+ *   8  : u32 字形数
+ *   12 : u32 位图区偏移
+ *   16 : 索引表[字形数]，每项 u32 码点 + u32 位图偏移（相对位图区），按码点升序
+ *   位图：((宽+7)/8)*高 字节/字，行优先，高位在左
+ */
+
+static int glyph_find(uint32_t cp, uint32_t *off)
+{
+  int lo = 0, hi = g_fc - 1;
+
+  while (lo <= hi)
+    {
+      int mid = (lo + hi) >> 1;
+      const uint8_t *e = g_font + 16 + (size_t)mid * 8;
+      uint32_t v = rd32(e);
+
+      if (v == cp) { *off = rd32(e + 4); return 1; }
+      if (v < cp)  { lo = mid + 1; } else { hi = mid - 1; }
+    }
+
+  return 0;
+}
+
+static int font_load(void)
+{
+  struct stat st;
+  int fd;
+
+  fd = open(FONT_PATH, O_RDONLY);
+  if (fd < 0)
+    {
+      /* SD 没挂就自己挂一次（没有自动挂载器） */
+      mkdir("/mnt", 0777);
+      mkdir("/mnt/sdcard", 0777);
+      mount("/dev/mmcsd0", "/mnt/sdcard", "vfat", 0, NULL);
+      fd = open(FONT_PATH, O_RDONLY);
+    }
+
+  if (fd < 0)
+    {
+      printf("[ui] 字库打不开 %s: %d（SD 未插或未挂载）\n", FONT_PATH, errno);
+      return -1;
+    }
+
+  if (fstat(fd, &st) != 0 || st.st_size < 24)
+    {
+      printf("[ui] 字库文件异常\n");
+      close(fd);
+      return -1;
+    }
+
+  g_fsz = (uint32_t)st.st_size;
+  g_font = (uint8_t *)malloc(g_fsz);
+  if (g_font == NULL)
+    {
+      printf("[ui] 字库缓冲 %u 字节分配失败\n", (unsigned)g_fsz);
+      close(fd);
+      return -1;
+    }
+
+  {
+    ssize_t got = read(fd, g_font, g_fsz);
+    close(fd);
+
+    if (got != (ssize_t)g_fsz)
+      {
+        printf("[ui] 字库只读到 %d/%u\n", (int)got, (unsigned)g_fsz);
+        free(g_font); g_font = NULL;
+        return -1;
+      }
+  }
+
+  if (memcmp(g_font, "JXFN", 4) != 0)
+    {
+      printf("[ui] 字库魔数不对\n");
+      free(g_font); g_font = NULL;
+      return -1;
+    }
+
+  g_gw    = (int)rd16(g_font + 4);
+  g_gh    = (int)rd16(g_font + 6);
+  g_fc    = (int)rd32(g_font + 8);
+  g_fdata = rd32(g_font + 12);
+
+  if (g_gw <= 0 || g_gw > 32 || g_gh <= 0 || g_gh > BAND_H ||
+      g_fc <= 0 || 16u + (uint32_t)g_fc * 8u > g_fsz || g_fdata > g_fsz)
+    {
+      printf("[ui] 字库参数越界 gw=%d gh=%d n=%d\n", g_gw, g_gh, g_fc);
+      free(g_font); g_font = NULL;
+      return -1;
+    }
+
+  g_font_ok = 1;
+  printf("[ui] 字库就绪: %d 字形 %dx%d, 文件 %u 字节\n",
+         g_fc, g_gw, g_gh, (unsigned)g_fsz);
+  return 0;
+}
+
+/****************************************************************************
+ * 绘制原语
+ ****************************************************************************/
+
+/* 把 g_scr 前 w*h 个像素送到 (x,y)。putarea 一次发完，比逐行 putrun 省
+ * 掉 h 次 setarea（每次 ~30us），满屏能省 10ms 量级。 */
+static void flush(int x, int y, int w, int h)
+{
+  if (w <= 0 || h <= 0) { return; }
+
+  if (g_pi.putarea != NULL)
+    {
+      g_pi.putarea(g_lcd, (fb_coord_t)y, (fb_coord_t)(y + h - 1),
+                   (fb_coord_t)x, (fb_coord_t)(x + w - 1),
+                   (FAR uint8_t *)g_scr, (fb_coord_t)(w * 2));
+    }
+  else
+    {
+      for (int r = 0; r < h; r++)
+        {
+          g_pi.putrun(g_lcd, (fb_coord_t)(y + r), (fb_coord_t)x,
+                      (FAR uint8_t *)(g_scr + (size_t)r * w), (size_t)w);
+        }
+    }
+}
+
+static void fill_rect(int x, int y, int w, int h, uint16_t c)
+{
+  if (!g_ready) { return; }
+
+  if (x < 0) { w += x; x = 0; }
+  if (y < 0) { h += y; y = 0; }
+  if (x + w > UI_W) { w = UI_W - x; }
+  if (y + h > UI_H) { h = UI_H - y; }
+  if (w <= 0 || h <= 0) { return; }
+
+  while (h > 0)
+    {
+      int bh = (h > BAND_H) ? BAND_H : h;
+      int n  = w * bh;
+
+      for (int i = 0; i < n; i++) { g_scr[i] = c; }
+      flush(x, y, w, bh);
+      y += bh;
+      h -= bh;
+    }
+}
+
+static void frame_rect(int x, int y, int w, int h, uint16_t c)
+{
+  fill_rect(x, y, w, 1, c);
+  fill_rect(x, y + h - 1, w, 1, c);
+  fill_rect(x, y, 1, h, c);
+  fill_rect(x + w - 1, y, 1, h, c);
+}
+
+/* 单倍文字（16x16）。y 到 y+g_gh-1 必须落在屏内。 */
+static void text1(int x, int y, const char *s, uint16_t fg, uint16_t bg)
+{
+  int stride, room, maxc, total, n = 0;
+  uint32_t cp;
+
+  if (!g_ready || !g_font_ok || s == NULL) { return; }
+  if (x < 0) { x = 0; }
+  if (y < 0 || y + g_gh > UI_H || x >= UI_W) { return; }
+
+  stride = (g_gw + 7) / 8;
+  room   = UI_W - x;
+  maxc   = room / g_gw;
+  if (maxc <= 0) { return; }
+
+  total = str_chars(s);
+  if (total > maxc) { total = maxc; }
+  if (total <= 0) { return; }
+
+  {
+    int pix = total * g_gh;
+    for (int i = 0; i < pix; i++) { g_scr[i] = bg; }
+  }
+
+  while (*s != '\0' && n < total)
+    {
+      uint32_t off;
+
+      s = u8next(s, &cp);
+      if (glyph_find(cp, &off))
+        {
+          const uint8_t *bm = g_font + g_fdata + off;
+
+          for (int r = 0; r < g_gh; r++)
+            {
+              const uint8_t *src = bm + (size_t)r * stride;
+              uint16_t      *dst = g_scr + (size_t)r * total + (size_t)n * g_gw;
+
+              for (int cx = 0; cx < g_gw; cx++)
+                {
+                  dst[cx] = (src[cx >> 3] & (0x80u >> (cx & 7))) ? fg : bg;
+                }
+            }
+        }
+
+      n++;
+    }
+
+  flush(x, y, total * g_gw, g_gh);
+}
+
+/* 双倍文字（32x32），给大号数值用。分两条带各刷一次。 */
+static void text2(int x, int y, const char *s, uint16_t fg, uint16_t bg)
+{
+  int stride, room, maxc, total;
+  uint32_t cp;
+
+  if (!g_ready || !g_font_ok || s == NULL) { return; }
+  if (x < 0) { x = 0; }
+  if (y < 0 || y + g_gh * 2 > UI_H || x >= UI_W) { return; }
+
+  stride = (g_gw + 7) / 8;
+  room   = UI_W - x;
+  maxc   = room / (g_gw * 2);
+  if (maxc <= 0) { return; }
+
+  total = str_chars(s);
+  if (total > maxc) { total = maxc; }
+  if (total <= 0) { return; }
+
+  for (int half = 0; half < 2; half++)
+    {
+      int r0 = half * (g_gh / 2);
+      int r1 = r0 + g_gh / 2;
+      int pix = total * g_gw * 2 * (g_gh / 2);
+      int n = 0;
+      const char *p = s;
+
+      for (int i = 0; i < pix; i++) { g_scr[i] = bg; }
+
+      while (*p != '\0' && n < total)
+        {
+          uint32_t off;
+
+          p = u8next(p, &cp);
+          if (glyph_find(cp, &off))
+            {
+              const uint8_t *bm = g_font + g_fdata + off;
+
+              for (int r = r0; r < r1; r++)
+                {
+                  const uint8_t *src = bm + (size_t)r * stride;
+                  int orow = (r - r0) * 2;
+
+                  for (int rep = 0; rep < 2; rep++)
+                    {
+                      uint16_t *dst = g_scr +
+                                      (size_t)(orow + rep) * (size_t)(total * g_gw * 2) +
+                                      (size_t)n * g_gw * 2;
+
+                      for (int cx = 0; cx < g_gw; cx++)
+                        {
+                          uint16_t v = (src[cx >> 3] & (0x80u >> (cx & 7))) ? fg : bg;
+                          dst[cx * 2] = v;
+                          dst[cx * 2 + 1] = v;
+                        }
+                    }
+                }
+            }
+
+          n++;
+        }
+
+      flush(x, y + half * (g_gh), total * g_gw * 2, g_gh);
+    }
+}
+
+/* 文字居中：cx 是中心 x */
+static void text_c(int cx, int y, const char *s, uint16_t fg, uint16_t bg)
+{
+  int w = str_chars(s) * g_gw;
+  text1(cx - w / 2, y, s, fg, bg);
+}
