+static void tile(int x, int y, int w, int h, const char *k,
+                 const char *v, const char *u, uint16_t vcol, int big)
+{
+  int ty = y + (big ? 6 : 8);
+
+  fill_rect(x, y, w, h, C_PANEL);
+  frame_rect(x, y, w, h, C_LINE2);
+
+  text1(x + 7, ty, k, C_DIM, C_PANEL);
+
+  if (big)
+    {
+      text2(x + 7, ty + 18, v, vcol, C_PANEL);
+    }
+  else
+    {
+      text1(x + 7, ty + 18, v, vcol, C_PANEL);
+    }
+
+  if (u != NULL && *u != '\0')
+    {
+      int vw = str_chars(v) * (big ? g_gw * 2 : g_gw);
+
+      text1(x + 9 + vw, ty + 18 + (big ? 16 : 0), u, C_DIM2, C_PANEL);
+    }
+}
