+/* 波形：把 g_wave 画到 (x,y,w,h) 的框里 */
+static void draw_wave(int x, int y, int w, int h)
+{
+  int n = g_wave_n;
+
+  if (!g_ready) { return; }
+  if (n <= 0 || w <= 0 || h <= 0) { return; }
+
+  {
+    int mid = h / 2;
+
+    fill_rect(x, y, w, h, C_PANEL2);
+
+    /* 逐列算 min/max，避免逐像素裁剪 */
+    for (int c = 0; c < w; c++)
+      {
+        int i0 = (int)((long long)c * n / w);
+        int i1 = (int)((long long)(c + 1) * n / w);
+        int lo = 32767, hi = -32768;
+
+        if (i1 <= i0) { i1 = i0 + 1; }
+        if (i1 > n)   { i1 = n; }
+
+        for (int i = i0; i < i1; i++)
+          {
+            int v = g_wave[i];
+            if (v < lo) { lo = v; }
+            if (v > hi) { hi = v; }
+          }
+
+        {
+          int y0 = mid - (int)((long long)hi * mid / 32768);
+          int y1 = mid - (int)((long long)lo * mid / 32768);
+
+          if (y1 < y0) { int t = y0; y0 = y1; y1 = t; }
+          if (y1 - y0 < 1) { y1 = y0 + 1; }
+          if (y0 < 0) { y0 = 0; }
+          if (y1 > h) { y1 = h; }
+
+          fill_rect(x + c, y + y0, 1, y1 - y0, C_CY);
+        }
+      }
+
+    fill_rect(x, y + mid, w, 1, RGB(0x14,0x28,0x32));
+    frame_rect(x, y, w, h, C_LINE);
+  }
+}
